var t=[{title:`Het trainingsdoel`,text:`Plyometrische oefeningen bouwen je vermogen op om snel kracht te leveren; buiten adem raken is niet het punt. Voorbeelden zijn kleine pogo-sprongetjes, squat jumps, zijwaartse sprongen en bounding. Snellere of hogere sprongen vragen meer van je coördinatie en geven meer impact, dus je beginniveau hangt af van je kracht, landingscontrole en trainingsverleden.`},{title:`Oefen een beheerste landing`,text:`Begin met lage, makkelijke sprongetjes en land door je heupen, knieën en enkels samen te buigen. Streef naar een gebalanceerd voetcontact en een beheerste romp, zonder vergrendelde knieën of luide, slordige landingen. Je knieën hoeven niet perfect stil te blijven, maar ze mogen niet plotseling de controle verliezen. Stop als je pijn voelt of blijft struikelen.`},{title:`Bouw één ding tegelijk op`,text:`Maak sprongen geleidelijk moeilijker, bijvoorbeeld van kleine tweevoetige sprongetjes naar bescheiden verticale sprongen voordat je herhaalde of eenbenige sprongen probeert. Hoge boxen, dieptesprongen en sprongen met gewicht vragen meer vaardigheid en zijn slechte eerste stappen. Voeg pas hoogte, snelheid of werk op één been toe als de makkelijkere herhalingen betrouwbaar blijven.`},{title:`Tel goede contacten`,text:`Voetcontacten, het aantal keren dat je voeten landen, worden vaak gebruikt om het plyometrische volume van het onderlichaam te meten. Als beginner heb je misschien maar een klein aantal beheerste contacten nodig, ook al noemen atletische programma’s hogere totalen. Rust genoeg tussen korte sets. Een vermoeiend sprongcircuit bouwt geen vermogen op zoals verse, explosieve herhalingen dat doen.`},{title:`TrainUp gebruiken`,text:`Het schema bevat sprongoefeningen alleen als je Profiel springen en het geluid dat ze maken toelaat, en je ondergrond en vloeroppervlak erbij passen. Ook je niveau telt mee. Past iets daarvan niet, train dan met krachtoefeningen of conditieoefeningen met lage impact. Doet een landing pijn, tik dan op “Ik voel pijn”: de oefening stopt meteen en blijft uit je schema’s tot je hem hervat in Profiel.`}];var i=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Samenvatting van de krachttrainingsrichtlijn van het ACSM 2026`,url:`https://acsm.org/resistance-training-guidelines-update-2026/`},{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};